<section class="auth-wrap"><div class="auth-card"><span class="eyebrow">ACCOUNT</span><h1><?=$register?'Join GameScore':'Welcome back'?></h1><p><?=$register?'Track games and build your personal watchlist.':'Sign in to your GameScore account.'?></p><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($register):?><label>Name<input name="name" required></label><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required minlength="8"></label><button class="button primary" type="submit"><?=$register?'Create account':'Sign in'?></button></form><p class="switch"><?=$register?'Already have an account?':'Need an account?'?> <a href="<?=url($register?'/login':'/register')?>"><?=$register?'Sign in':'Create one'?></a></p></div></section>